SELECT country, CASE WHEN age >= 72 THEN 'high' WHEN age >= 28 THEN 'mid' ELSE 'low' END AS age_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values, MIN(signup_date) AS first_signup_date, MAX(credit_limit) AS max_credit_limit FROM customers WHERE is_active AND (age IS NOT NULL OR name IS NOT NULL) GROUP BY ROLLUP(country, CASE WHEN age >= 72 THEN 'high' WHEN age >= 28 THEN 'mid' ELSE 'low' END);
